#!/usr/bin/env python3
"""Regenerate scalar-sequence oracle vectors using PrefixSpan-py 0.5.2.

Install only development references: python -m pip install -r scripts/reference-requirements.txt
The generated test is not production code and is excluded from implementation LOC.
"""
import argparse
import json
import random
import re
from pathlib import Path
from prefixspan import PrefixSpan


def generate():
    rng = random.Random(20261109)
    lines = ["// Reference vectors: PrefixSpan-py 0.5.2 (MIT), deterministic seed 20261109.",
             "// Generated by scripts/reference_vectors.py; not counted as production code."]
    for case in range(64):
        scalar = [[rng.randrange(4) for _ in range(rng.randrange(7))] for _ in range(4)]
        db = [[[item] for item in sequence] for sequence in scalar]
        for minimum in (1, 2):
            reference = PrefixSpan(scalar)
            reference.maxlen = 4
            pairs = sorted((";".join(str(item) for item in sequence), count)
                           for count, sequence in reference.frequent(minimum))
            literal = ",".join("("+json.dumps(key)+","+str(count)+")" for key,count in pairs)
            lines += [f'test "Python PrefixSpan scalar differential {case}/{minimum}" {{',
                      '  let db = @moonseqmine.database('+json.dumps(db,separators=(',',':'))+')',
                      '  let actual : Map[String, Int] = Map([])',
                      f'  for record in @moonseqmine.mine(db,@moonseqmine.options({minimum},max_items=4)) {{',
                      '    actual[@moonseqmine.pattern_key(record.pattern)] = record.support',
                      '  }', '  assert_eq(actual,Map(['+literal+']))', '}']
    return '\n'.join(lines)+'\n'


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args = parser.parse_args()
    path = Path(__file__).resolve().parents[1]/'src'/'reference_test.mbt'
    generated = generate()
    # moon fmt changes layout, so compare lexical content ignoring whitespace.
    # All generated strings are decimal IDs separated by semicolons: no spaces.
    if args.check:
        def normalize(text):
            text = re.sub(r'//[^\n]*', '', text)
            text = ''.join(text.split()).replace('Int32','Int')
            return re.sub(r',(?=[\]\)])', '', text)
        if normalize(path.read_text(encoding='utf-8')) != normalize(generated):
            raise SystemExit('Reference fixture mismatch; regenerate and inspect diff')
        print('128 deterministic PrefixSpan reference fixtures verified')
    else:
        path.write_text(generated,encoding='utf-8')
        print('Wrote 128 deterministic PrefixSpan reference fixtures')

if __name__ == '__main__':
    main()

